区间查询我们现在已经能完成这些节点上区间的查询了。不难发现，我们只需要把一些线段树上区间求并集，就可以得到任意区间。我们只要找离根节点的最短路的距离最低的、且是查询区间的子集的节点，就是那几个构成查询区间的线段树上区间。这个部分比较简单，我就直接给代码了，还是以求和为例：
int raw[N+1];int seg[4*N];int get(int left,int right,int query_left,int query_right,int index){    //是否是查询区间的子集    if(left&lt;=query_left&amp;&amp;right&lt;=query_right){        return seg[index];    }    int mid=left+(right-left)/2;    int ret=0;    //左叶子与查询区间有交集。query_right改成mid是缩小查询区间（分治思想）。    if(query_left&lt;=mid) ret+=get(left,mid,query_left,mid,2*index);    //右叶子与查询区间有交集。query_left改成mid+1同理    if(query_right&gt;=mid+1) ret+=get(mid+1,right,mid+1,query_right,2*index+1);    return ret;}int main(){    //省略把数据读取到raw数组    build(1,n,1);//n为数组长度    get(1,n,a,b,1);//查询区间为[a,b]}
